// Builds an approval envelope for the invoice your accounting system sends to this webhook.
// Request body: invoice_number, vendor, amount, currency, pdf_url (a URL SignatureAPI can fetch, such as an upload URL),
// approver { name, email } who reviews it, and signer { name, email } who signs it off.
const input = $input.first().json.body;
for (const field of ['invoice_number', 'vendor', 'amount', 'currency', 'pdf_url']) {
  if (!input?.[field]) throw new Error(`The request needs ${field}`);
}
for (const person of ['approver', 'signer']) {
  if (!input[person]?.name || !input[person]?.email) throw new Error(`The request needs ${person}.name and ${person}.email`);
}

const envelope = {
  title: `Invoice ${input.invoice_number} from ${input.vendor}: ${input.currency} ${input.amount}`,
  message: 'Please review this invoice.',
  routing: 'sequential', // the approver reviews first; the signer gets it only after approval
  topics: ['invoices'],
  metadata: { invoice_number: String(input.invoice_number) },
  documents: [
    {
      key: 'invoice',
      url: input.pdf_url,
      format: 'pdf',
      places: [{ key: 'signoff', type: 'signature', recipient_key: 'signer' }],
      fixed_positions: [{ place_key: 'signoff', page: 1, top: 680, left: 72 }],
    },
  ],
  recipients: [
    { type: 'approver', key: 'approver', name: input.approver.name, email: input.approver.email },
    { type: 'signer', key: 'signer', name: input.signer.name, email: input.signer.email },
  ],
};

return [{ json: { envelope } }];
